mapper.select:
SELECT s.*, e.name AS event_name, e.category AS category, m.name AS meeting_name, u.real_name AS referee_name, (SELECT COUNT(*) FROM t_schedule_athlete sa WHERE sa.schedule_id = s.id) AS athlete_count FROM t_schedule s LEFT JOIN t_event e ON s.event_id = e.id LEFT JOIN t_meeting m ON s.meeting_id = m.id LEFT JOIN ssms_auth.t_user u ON s.referee_id = u.id WHERE s.deleted = 0
AND s.meeting_id = #{meetingId}
AND s.event_id = #{eventId}
AND s.event_date = #{eventDate}
AND s.status = #{status}
AND s.referee_id = #{refereeId}
ORDER BY s.event_date ASC, s.start_time ASC
